"""Structured data for the process pipeline graph: the core pipeline the README names.

The graph draws the programs that the root README's "Core pipeline" section names, and
``py/main_ws_bot.py real``, whose saves and post-run download feed that pipeline. It draws
the stores those programs read and write among Hebrew Wikisource, ``in/mam-ws/``,
``in/mam-ws-special/``, ``MAM-parsed/plus/``, ``MAM-simple/``, ``MAM-for-Sefaria/``,
``MAM-OSIS/`` and ``gh-pages/MAM-with-doc/``, and nothing else. A program that
``py/main_0_mega.py`` runs is a solid box labelled with its step ids; a program it does not
run is a dashed gray box.

``py/tests/test_mega_coverage.py`` checks every program node against the mega's ``_STEPS``,
its ``NOT_IN_MEGA`` declarations and the README's "Core pipeline" section.
"""

from dataclasses import dataclass


@dataclass(frozen=True)
class StoreNode:
    node_id: str
    label: str


@dataclass(frozen=True)
class ProgramNode:
    node_id: str
    # The program as py/tests/test_mega_coverage.py keys it: a path, then a subcommand.
    program: str
    # The py/main_0_mega.py steps that run it; none for a program run by hand.
    step_ids: tuple[str, ...] = ()

    @property
    def label(self) -> str:
        name = self.program.removeprefix("py/")
        if not self.step_ids:
            return name
        steps = "mega step" if len(self.step_ids) == 1 else "mega steps"
        return f"{name}\n{steps}: {', '.join(self.step_ids)}"


@dataclass(frozen=True)
class Edge:
    source_id: str
    target_id: str
    tooltip: str | None = None


